import {ACCOUNT_CHANGED,ACCOUNT_KEY} from './account-api.js?v=f1b44b39b0a6';
import {MAP_MODES,LAYERS,TOOL_LABELS,clone,makeId,newPlan,emptyStep,duplicateStep,createItem,moveItem,changeConditions,visibleItems,planFromGuide} from './maps-model.js?v=d29d1c20e4a9';
import {renderScene,mapEscape as e} from './maps-renderer.js?v=c4fa0c7979f6';
import {mountMapInput} from './maps-input.js?v=b69b536e8c5f';
import {createMapStorage} from './maps-storage.js?v=918aa7cf8e03';
import {createMapCloud,mapAccount} from './maps-cloud.js?v=02848c6236c9';
import {createPlanSession} from './maps-session.js?v=bddbd150580d';
import {exportJSON,importJSON,exportPNG} from './maps-export.js?v=ba2df6d27641';
import {mapShareURL,researchDraft,stageResearchDraft} from './maps-links.js?v=9ccb6919d60a';
import {button,mapHeader,stageToolbar,toolsHTML,conditionsHTML,inspectorHTML,timelineHTML,timelineStepLabel,explorePanel,guidePanel,sourceHTML} from './maps-editor.js?v=d488b506571e';

const BETA_ACK='manor-maps-beta:1';
const loading='<div class="loading-screen"><span class="loading-orbit" aria-hidden="true"></span><p>맵을 불러오고 있습니다.</p></div>';
export function mountMaps(root,{characters={},mapId='',shareId='',planId='',navigate=()=>{}}={}){
 let alive=true,catalog=[],map,session,input,mode='explore',floor='ground',step=0,selected='',tool='select',points=[],search='',guide=null,guidePlan=null,guideStep=0;
 let playing=false,playTimer=0,statusText='',statusError=false,accountBlocked=false,shared=null,busy=false,libraryRows=[],librarySource='local',shareRows=[],lastShare=null;
 const owner=mapAccount()?.accountId||'guest',storage=createMapStorage(),cloud=createMapCloud(),fetchController=new AbortController(),layers=new Set(Object.keys(LAYERS)),guideFilters={faction:'',situation:'',characterId:''};
 const $=selector=>root.querySelector(selector);
 const getPlan=()=>mode==='guides'&&guidePlan?guidePlan:shared?.plan||session.get();
 const getStep=()=>mode==='guides'?guideStep:step;
 const editable=()=>mode==='tactics'&&!shared&&!accountBlocked;
 function status(text,error=false){statusText=text;statusError=error;const node=$('[data-map-status]');if(node){node.textContent=text;node.classList.toggle('is-error',error);}}
 function closeDialog(){const dialog=$('dialog');dialog?.close();dialog?.remove();}
 function dialog(title,html){closeDialog();const node=document.createElement('dialog');node.className='maps-dialog';node.setAttribute('aria-label',title);node.innerHTML=`<div class="maps-dialog-head"><h2>${e(title)}</h2>${button('close-dialog','<span aria-hidden="true">×</span><span class="sr-only">닫기</span>')}</div><div class="maps-dialog-body">${html}</div>`;root.append(node);node.showModal();return node;}
 function betaInfo(){dialog('맵 베타 이용 안내',`<span class="beta-badge">BETA</span><p>맵 기능은 시험 운영 중입니다. 지도·공략·저장 방식이 개선될 수 있습니다.</p><ul><li>공개 미니맵을 바탕으로 하며 현재 게임 버전과 다를 수 있습니다.</li><li>표식·경로는 사용자 가정입니다. 해독기·의자·시작 위치는 직접 확인해 주세요.</li><li>초기 공략은 실전 검증 전 연습 예시입니다. 재생은 실제 게임 시뮬레이션이 아닙니다.</li><li>브라우저 데이터 삭제 시 초안이 사라집니다. 중요한 전술은 계정 저장이나 JSON 내보내기를 이용하세요.</li><li>공유 링크는 받은 사람이 열 수 있습니다. 개인정보를 적지 마세요.</li></ul><p>자동 길찾기와 실시간 공동 편집은 이번 베타에 포함되지 않습니다.</p>${button('ack-beta','확인하고 시작',{primary:true})}`);}
 function stop(){playing=false;clearTimeout(playTimer);playTimer=0;const toggle=$('[data-map-action="play"]');if(toggle)toggle.textContent='단계 재생';}
 function selectedItem(){return session.get().steps[step]?.items.find(i=>i.id===selected);}
 function update(fn){if(!editable())return;if(session.change(fn)){step=Math.min(step,session.get().steps.length-1);render();}}
 function render(){
  if(!alive||!map)return;const focused=document.activeElement?.dataset?.mapItem;const opened=[...root.querySelectorAll('details[open]')].map(n=>n.className);const view=input?.getView();input?.destroy();input=null;
  const plan=getPlan(),index=getStep(),readOnly=!!shared||mode==='guides';
  root.innerHTML=`<div class="maps-app">${mapHeader(catalog,map,{mode,readonly:!!shared})}${shared?`<div class="maps-shared"><strong>공유 전술 · 읽기 전용</strong><span>공유 당시 버전 ${shared.revision} · 작성자가 바꿔도 이 내용은 유지됩니다.</span>${button('copy-shared','내 전술로 복사',{primary:true})}${button('leave-share','맵으로 돌아가기')}</div>`:''}${accountBlocked?`<div class="maps-warning" role="alert">로그인 계정이 변경되었습니다. 화면을 새로고침해 현재 계정의 전술을 선택해 주세요. ${button('reload','새로고침')}</div>`:''}${mode==='tactics'||shared?`<div class="maps-planbar"><label>전술 제목<input data-map-field="title" value="${e(plan.title)}" maxlength="80"${shared?' readonly':''}></label><div class="maps-actions">${shared?'':button('undo','실행 취소',{disabled:!session.history.canUndo()})+button('redo','다시 실행',{disabled:!session.history.canRedo()})+button('copy-plan','사본 만들기')+button('save-cloud','계정 저장',{primary:true})+button('share','공유')}${button('export-json','JSON')}${button('export-png','이미지')}</div></div>`:''}<p class="maps-status${statusError?' is-error':''}" data-map-status role="status">${e(statusText)}</p><div class="maps-workspace"><section class="maps-canvas-card" aria-label="지도 작업 공간">${stageToolbar(map,floor,layers)}${editable()?toolsHTML(tool):''}<div class="maps-stage" tabindex="0" aria-label="지도 · 두 손가락 확대, 드래그 이동"><div class="maps-stage-content"></div></div><div class="maps-map-caption"><span>${e(map.name)} · ${map.floors.find(f=>f.id===floor).name}</span><span data-map-scale>100%</span></div><div class="maps-landmark-info" data-map-landmark-info></div>${mode==='tactics'||shared||mode==='guides'&&guidePlan?timelineHTML(plan,index,{readonly:readOnly,playing}):''}</section><aside class="maps-sidebar">${mode==='explore'&&!shared?explorePanel(map,search):mode==='guides'&&!shared?guidePanel(map,{...guideFilters,characters,guide,guideStep}):shared?`<section><p class="maps-kicker">SHARED TACTIC</p><h2>${e(plan.title)}</h2><p class="maps-hint">${plan.conditions.server==='global'?'글로벌':'중국'} · ${plan.conditions.mode==='practice'?'연습':'일반 1 대 4'} · ${plan.conditions.faction==='survivor'?'생존자':'감시자'}${plan.conditions.characterId?' · '+e(characters[plan.conditions.characterId]?.name||''):''} · ${e(plan.mapRevision)}</p><p class="maps-step-note">${e(plan.conditions.note||'별도 조건 메모가 없습니다.')}</p><p class="maps-hint">표식은 사용자 가정입니다. 공유자의 실전 검증 여부는 별도로 확인해 주세요.</p></section>`:conditionsHTML(plan,characters)+inspectorHTML(plan,step,selected,characters)}</aside></div>${sourceHTML(map)}<input type="file" data-map-file accept=".json,application/json" hidden></div>`;
  renderSceneOnly();
  input=mountMapInput($('.maps-stage'),{bounds:map.bounds,getTool:()=>editable()?tool:'pan',onPoint:place,onSelect:id=>{if(editable()){selected=id;renderInspector();}},onMove:(id,dx,dy)=>{if(editable())update(p=>{const item=p.steps[step].items.find(i=>i.id===id);if(item)moveItem(item,dx,dy,map.bounds);});},onLandmark:showLandmark,onView:view=>{const n=$('[data-map-scale]');if(n)n.textContent=Math.round(view.scale*100)+'%';},onFinish:finishPath,onCancel:cancelPath});
  for(const name of opened){const details=root.querySelector('details.'+name.split(' ').join('.'));if(details)details.open=true;}if(view)input.setView(view);drawDraft();const out=$('[data-map-action="zoom-out"]'),inside=$('[data-map-action="zoom-in"]');out?.setAttribute('aria-label','지도 축소');inside?.setAttribute('aria-label','지도 확대');if(focused)root.querySelector(`[data-map-item="${focused}"]`)?.focus({preventScroll:true});
 }
 function renderSceneOnly(){const focused=document.activeElement?.dataset?.mapItem,plan=getPlan();$('.maps-stage-content').innerHTML=renderScene(map,{floor,layers,items:(mode==='explore'||mode==='guides'&&!guidePlan)&&!shared?[]:visibleItems(plan,getStep(),floor,layers),characters,selected:editable()?selected:'',view:input?.getView()});if(focused)root.querySelector(`[data-map-item="${focused}"]`)?.focus({preventScroll:true});}
 function renderInspector(){if(!editable())return;$('.maps-sidebar').innerHTML=conditionsHTML(session.get(),characters)+inspectorHTML(session.get(),step,selected,characters);renderSceneOnly();}
 function showLandmark(id){const point=map.landmarks.find(p=>p.id===id);if(!point)return;input.focus(point);$('[data-map-landmark-info]').textContent=point.name+' · 참조 자료의 근사 위치 · 실제 배치 확인 필요';}
 function drawDraft(){const node=$('.maps-draft');if(node)node.innerHTML=points.length?`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#f4c85c" stroke-width="5" stroke-dasharray="8 5"/>${points.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6" fill="#f4c85c"/>`).join('')}`:'';const bar=$('.maps-drawing');if(bar){bar.hidden=!points.length;$('[data-map-draft-count]').textContent=points.length+'/80개 지점';}}
 function cancelPath(){points=[];drawDraft();}
 function finishPath(){if(!editable()||!['path','arrow'].includes(tool))return;if(points.length<2){status('경로에 두 지점 이상을 찍어 주세요.',true);return;}const item=createItem(tool,points[0],floor,{points:clone(points),color:session.get().conditions.faction==='hunter'?'red':'green'});item.needsReview=true;points=[];tool='select';selected=item.id;try{update(p=>p.steps[step].items.push(item));}catch(error){status(error.message,true);}}
 function place(point){if(!editable())return;if(['select','pan'].includes(tool)){selected='';renderInspector();return;}if(['path','arrow'].includes(tool)){if(points.length>=80){status('경로는 80개 지점까지 만들 수 있습니다.',true);return;}points.push(point);drawDraft();return;}const plan=session.get(),label=tool==='number'?String(plan.steps[step].items.filter(i=>i.kind==='number').length+1):tool==='note'?'메모':'';const item=createItem(tool,point,floor,{label,characterId:tool==='character'?plan.conditions.characterId:'',color:plan.conditions.faction==='hunter'?'red':'green'});selected=item.id;tool='select';try{update(p=>p.steps[step].items.push(item));}catch(error){status(error.message,true);}}
 function changeStep(index){selected='';cancelPath();if(mode==='guides'){guideStep=index;floor=guide.steps[index].floor||'ground';}else{step=index;const first=getPlan().steps[index].items[0];if(first)floor=first.floor;}render();}
 function playNext(){if(!alive||!playing||document.hidden)return;const plan=getPlan(),index=getStep();playTimer=setTimeout(()=>{if(index+1>=plan.steps.length){stop();render();return;}changeStep(index+1);playNext();},plan.steps[index].duration*1000);}
 function beginPlay(){if(playing){stop();render();return;}if(getStep()===getPlan().steps.length-1)changeStep(0);playing=true;render();playNext();}
 async function changeMap(id){const next=catalog.find(m=>m.id===id);if(!next||next.id===map.id)return;await session.flush();stop();cancelPath();input?.destroy();input=null;map=next;floor='ground';step=0;selected='';guide=null;guidePlan=null;await session.open(newPlan(map));status('새 전술은 편집을 시작하면 브라우저에 저장됩니다.');render();}
 async function openPlan(plan,record,{copy=false}={}){stop();cancelPath();await (copy?session.copy(plan):session.open(plan,record));map=catalog.find(m=>m.id===session.get().mapId);input?.destroy();input=null;floor=session.get().steps[0].items[0]?.floor||'ground';mode='tactics';step=0;selected='';shared=null;render();}
 async function library(source=librarySource){librarySource=source;dialog('내 전술',loading);const rows=source==='cloud'?(await cloud.list()).plans:await storage.list(source==='guest'?'guest':owner);if(!alive)return;libraryRows=rows;dialog('내 전술',`<div class="maps-actions">${button('library-local','이 브라우저',{pressed:source==='local'})}${button('library-cloud','계정',{pressed:source==='cloud'})}${owner!=='guest'?button('library-guest','비로그인 초안',{pressed:source==='guest'}):''}${button('new-plan','새 전술')}</div><p class="maps-hint">${source==='cloud'?'계정의 최신 저장본을 불러옵니다. 열기 전에 현재 전술을 사본으로 보관할 수 있습니다.':'이 브라우저에 저장된 초안입니다. 브라우저 데이터 삭제 시 사라집니다.'}</p><div class="maps-saved-list">${rows.map((r,i)=>`<article><strong>${e(r.plan?.title||r.title)}</strong><small>${e(catalog.find(m=>m.id===(r.plan?.mapId||r.mapId))?.name||'맵')} · ${new Date(r.updatedAt).toLocaleDateString('ko-KR')}${source==='cloud'?' · 버전 '+r.revision:''}</small><div class="maps-actions">${button('open-saved',source==='guest'?'내 전술로 복사':'열기',{value:String(i)})}${source==='guest'?'':button('delete-saved','삭제',{value:String(i)})}</div></article>`).join('')||'<p class="maps-empty">저장된 전술이 없습니다.</p>'}</div>${button('share-list','공유 링크 관리')}`);}
 async function openSaved(index){const row=libraryRows[index];if(!row)return;if(librarySource==='cloud'){dialog('계정 전술 불러오기',`<p>계정의 버전 ${row.revision}을 불러옵니다. 같은 전술의 브라우저 초안이 있다면 계정 내용으로 바뀝니다.</p><div class="maps-actions">${button('cloud-open-confirm','불러오기',{value:row.id,primary:true})}${button('keep-copy-open','현재 전술을 사본으로 보관 후 열기',{value:row.id})}</div>`);}else await openPlan(row.plan,row,{copy:librarySource==='guest'});}
 async function loadCloud(id,copy=false){if(copy)await session.copy();await session.openCloud(id);map=catalog.find(m=>m.id===session.get().mapId);input?.destroy();input=null;mode='tactics';shared=null;step=0;floor=session.get().steps[0].items[0]?.floor||'ground';selected='';render();}
 function saveConflict(error){if(error.code==='map_conflict'||error.code==='local_conflict'){dialog('저장 버전이 달라졌습니다',`<p>${e(error.message)}</p><p>현재 편집 내용은 자동으로 덮어쓰지 않습니다.</p><div class="maps-actions">${button('copy-plan','내 변경을 사본으로 보관',{primary:true})}${error.code==='map_conflict'?button('conflict-cloud','계정 내용 불러오기'):button('library-local','브라우저 목록 다시 확인')}</div>`);}else{const message=error.name==='AbortError'?'요청 시간이 초과되었습니다. 다시 시도해 주세요.':error.message;status(message,true);if($('dialog'))dialog('요청을 완료하지 못했습니다',`<p>${e(message)}</p>${button('close-dialog','확인')}`);}}
 async function share(){if(owner==='guest')throw Error('공유 링크는 로그인 후 만들 수 있습니다. JSON 파일은 로그인 없이 내보낼 수 있습니다.');dialog('읽기 전용 링크 만들기',`<p>현재 전술을 계정에 저장한 뒤, 이 버전의 복사본을 공유합니다. 링크를 받은 사람은 로그인 없이 볼 수 있습니다.</p><p>내 전술을 수정해도 기존 링크 내용은 바뀌지 않습니다. 공유 관리에서 링크를 취소할 수 있습니다.</p>${button('publish','계정에 저장하고 링크 만들기',{primary:true})}`);}
 async function publish(){const snapshot=await session.saveCloud();const share=await cloud.publish(snapshot.plan.id,snapshot.revision,makeId());if(!alive)return;lastShare={...share,plan:snapshot.plan,map:catalog.find(m=>m.id===snapshot.plan.mapId)};showShare(share.id);}
 function showShare(id){dialog('공유 링크',`<p>이 링크는 공유 당시 전술을 읽기 전용으로 보여 줍니다.</p><label>공유 주소<input readonly data-map-share-url value="${e(mapShareURL(id))}"></label><div class="maps-actions">${button('copy-link','주소 복사',{value:id,primary:true})}${lastShare?.id===id?button('attach-research','연구실에 첨부'):''}${button('share-list','공유 관리')}</div><p class="maps-hint">연구실에서는 초안을 검토한 뒤 직접 등록합니다.</p>`);}
 async function shares(){dialog('공유 링크 관리',loading);shareRows=(await cloud.shares()).shares;if(!alive)return;dialog('공유 링크 관리',`<p class="maps-hint">취소한 링크는 더 이상 열 수 없습니다. 이미 내려받은 이미지나 JSON 파일은 회수되지 않습니다.</p><div class="maps-saved-list">${shareRows.map((r,i)=>`<article><strong>${e(r.title)}</strong><small>공유 버전 ${r.revision}</small><div class="maps-actions">${button('show-share','주소 보기',{value:r.id})}${button('revoke-share','링크 취소',{value:String(i)})}</div></article>`).join('')||'<p>활성 공유 링크가 없습니다.</p>'}</div>`);}
 async function runAction(action,value){
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='help'){betaInfo();return;}
  if(action==='ack-beta'){try{localStorage.setItem(BETA_ACK,'1');}catch{}closeDialog();return;}
  if(action==='reload'){location.reload();return;}
  if(accountBlocked)return;
  if(action==='map'){await changeMap(value);return;}
  if(action==='mode'){stop();cancelPath();mode=Object.hasOwn(MAP_MODES,value)?value:'explore';selected='';render();return;}
  if(action==='floor'){cancelPath();floor=value;selected='';render();return;}
  if(action==='zoom-in'||action==='zoom-out'){input.zoom(action==='zoom-in'?1.25:.8);return;}
  if(action==='reset-view'){input.reset();return;}
  if(action==='landmark'){showLandmark(value);return;}
  if(action==='tool'){if(!editable())return;cancelPath();tool=value;render();return;}
  if(action==='finish-path'){finishPath();return;}
  if(action==='cancel-path'){cancelPath();return;}
  if(action==='undo'||action==='redo'){if(editable()){session[action]();step=Math.min(step,session.get().steps.length-1);selected='';render();}return;}
  if(action==='delete-item'){update(p=>{p.steps[step].items=p.steps[step].items.filter(i=>i.id!==selected);});selected='';return;}
  if(action==='review-item'){update(p=>{const i=p.steps[step].items.find(i=>i.id===selected);if(i)i.needsReview=false;});return;}
  if(action==='step'){stop();changeStep(Number(value));return;}
  if(action==='play'){beginPlay();return;}
  if(['add-step','copy-step','step-up','step-down','remove-step'].includes(action)){
   stop();update(p=>{if(action==='add-step'){p.steps.push(emptyStep((p.steps.length+1)+'단계'));step=p.steps.length-1;}if(action==='copy-step'){duplicateStep(p,step);step++;}if(action==='remove-step'&&p.steps.length>1){p.steps.splice(step,1);step=Math.max(0,step-1);}if(action==='step-up'&&step>0){[p.steps[step-1],p.steps[step]]=[p.steps[step],p.steps[step-1]];step--;}if(action==='step-down'&&step<p.steps.length-1){[p.steps[step+1],p.steps[step]]=[p.steps[step],p.steps[step+1]];step++;}});return;
  }
  if(action==='guide'){stop();guide=map.guides.find(g=>g.id===value);guidePlan=planFromGuide(map,guide);guideStep=0;floor=guide.steps[0].floor||'ground';render();return;}
  if(action==='use-guide'){await openPlan(guidePlan,{}, {copy:true});return;}
  if(action==='copy-plan'||action==='copy-shared'){await openPlan(getPlan(),{}, {copy:true});await session.flush();status('새 사본을 만들었습니다.');if(action==='copy-shared')navigate({v:'maps',plan:session.get().id});return;}
  if(action==='leave-share'){navigate({v:'maps'});return;}
  if(action==='new-plan'){await openPlan(newPlan(map));return;}
  if(action==='library'||action==='library-local'){await session.flush();await library('local');return;}
  if(action==='library-cloud'){await library('cloud');return;}
  if(action==='library-guest'){await library('guest');return;}
  if(action==='open-saved'){await openSaved(Number(value));return;}
  if(action==='cloud-open-confirm'||action==='keep-copy-open'){await loadCloud(value,action==='keep-copy-open');return;}
  if(action==='conflict-cloud'){dialog('계정 내용 불러오기',`<p>현재 변경을 대신해 계정 저장본을 엽니다.</p>${button('cloud-open-confirm','계정 내용 불러오기',{value:session.get().id,primary:true})}${button('keep-copy-open','사본 보관 후 불러오기',{value:session.get().id})}`);return;}
  if(action==='delete-saved'){const row=libraryRows[Number(value)];dialog('전술 삭제',`<p>${e(row.plan?.title||row.title)}을 삭제합니다.${librarySource==='cloud'?' 이 전술의 공유 링크도 취소됩니다. 브라우저 사본은 남습니다.':''}</p>${button('delete-confirm','삭제',{value,primary:true})}`);return;}
  if(action==='delete-confirm'){const row=libraryRows[Number(value)],id=row.plan?.id||row.id;if(librarySource==='cloud')await cloud.remove(id,row.revision);else{await storage.remove(owner,id);if(session.get().id===id)await openPlan(newPlan(map));}await library();return;}
  if(action==='save-cloud'){await session.saveCloud();return;}
  if(action==='share'){await share();return;}
  if(action==='publish'){await publish();return;}
  if(action==='share-list'){await shares();return;}
  if(action==='show-share'){showShare(value);return;}
  if(action==='copy-link'){const url=mapShareURL(value);try{await navigator.clipboard.writeText(url);status('공유 주소를 복사했습니다.');}catch{const field=$('[data-map-share-url]');field?.focus();field?.select();status('주소를 길게 누르거나 복사해 주세요.');}return;}
  if(action==='revoke-share'){const row=shareRows[Number(value)];dialog('공유 링크 취소',`<p>${e(row.title)}의 공유 버전 ${row.revision} 링크를 취소합니다.</p>${button('revoke-confirm','링크 취소',{value:row.id,primary:true})}`);return;}
  if(action==='revoke-confirm'){await cloud.revoke(value);if(lastShare?.id===value)lastShare=null;await shares();return;}
  if(action==='attach-research'){stageResearchDraft(researchDraft(lastShare.map,lastShare.plan,lastShare.id));navigate({v:'laboratory',draft:'map',topic:'strategy'});return;}
  if(action==='import'){closeDialog();$('[data-map-file]').click();return;}
  if(action==='export-json'){exportJSON(getPlan());status('전술 JSON을 내보냈습니다.');return;}
  if(action==='export-png'){status('이미지를 만드는 중…');await exportPNG(map,getPlan(),{step:getStep(),floor,layers,characters});status('현재 단계의 이미지를 내보냈습니다.');}
 }
 async function click(event){const target=event.target.closest('[data-map-action]');if(!target||!root.contains(target))return;event.preventDefault();if(busy)return;busy=true;target.disabled=true;try{await runAction(target.dataset.mapAction,target.dataset.value);}catch(error){saveConflict(error);}finally{busy=false;if(target.isConnected)target.disabled=false;}}
 async function change(event){const target=event.target;if(target.matches('[data-map-layer]')){target.checked?layers.add(target.dataset.mapLayer):layers.delete(target.dataset.mapLayer);renderSceneOnly();return;}
  if(target.matches('[data-map-file]')){try{await openPlan(await importJSON(target.files[0]),{}, {copy:true});status('전술 파일을 새 사본으로 가져왔습니다.');}catch(error){saveConflict(error);}return;}
  const field=target.dataset.mapField;if(!field||accountBlocked)return;if(event.type==='input'&&field==='title'&&!target.value.trim())return;
  if(field.startsWith('guide.')){guideFilters[field.slice(6)]=target.value;guide=null;guidePlan=null;guideStep=0;stop();render();return;}
  if(!editable())return;
  try{const changed=session.change(p=>{const value=target.type==='number'||target.type==='range'?Number(target.value):target.value;if(field==='title')p.title=value;else if(field.startsWith('step.'))p.steps[step][field.slice(5)]=value;else if(field.startsWith('item.')){const item=p.steps[step].items.find(i=>i.id===selected);if(item)item[field.slice(5)]=value;}else if(field.startsWith('condition.')){const c={...p.conditions,[field.slice(10)]:value};if(field==='condition.faction'){c.characterId='';c.situation=value==='hunter'?'hunt':'kite';}changeConditions(p,c);}});if(!changed)return;if(field.startsWith('item.')||field.startsWith('condition.'))renderSceneOnly();if(field==='step.title'){const label=$('[data-map-action="step"][data-value="'+step+'"]');if(label)label.innerHTML=timelineStepLabel(session.get().steps[step],step);}const undo=$('[data-map-action="undo"]'),redo=$('[data-map-action="redo"]');if(undo)undo.disabled=!session.history.canUndo();if(redo)redo.disabled=!session.history.canRedo();if(field.startsWith('condition.')&&field!=='condition.note'){const current=$('.maps-conditions');if(current){current.outerHTML=conditionsHTML(session.get(),characters);$('.maps-conditions').open=true;}if(session.get().steps.some(s=>s.items.some(i=>i.needsReview)))status('조건이 바뀌어 경로를 재확인 상태로 표시했습니다.');}}catch(error){status(error.message,true);}
 }
 function searchChange(event){if(event.target.dataset.mapField&&event.target.matches('input:not([type=file]),textarea')){change(event);return;}if(!event.target.matches('[data-map-search]'))return;search=event.target.value;const list=$('.maps-regions');list.innerHTML=map.landmarks.filter(l=>l.name.includes(search)).map(l=>button('landmark',e(l.name),{value:l.id})).join('')||'<p>일치하는 구역이 없습니다.</p>';}
 function accountChange(event){if(event?.type==='storage'&&event.key!==ACCOUNT_KEY)return;const next=mapAccount()?.accountId||'guest';if(next!==owner){stop();session?.flush().catch(()=>{});accountBlocked=true;status('계정이 변경되었습니다. 새로고침 후 이용해 주세요.',true);render();}}
 function visibility(){if(document.hidden){const target=document.activeElement;if(root.contains(target)&&target.dataset?.mapField)change({target});stop();session?.flush().catch(()=>{});}else accountChange();}
 function beforeUnload(event){if(session?.hasPending()){session.flush().catch(()=>{});event.preventDefault();event.returnValue='';}}
 async function init(){root.innerHTML=loading;const timer=setTimeout(()=>fetchController.abort(),15000);try{const response=await fetch(new URL('./maps/catalog.json?v=4e98f05c00bc',import.meta.url),{signal:fetchController.signal});if(!response.ok)throw Error('지도 자료를 불러오지 못했습니다.');const data=await response.json();clearTimeout(timer);if(!alive)return;catalog=data.maps;map=catalog.find(m=>m.id===mapId)||catalog[0];session=createPlanSession({initial:newPlan(map),owner,storage,cloud,onStatus:status});if(planId&&!shareId){const saved=(await storage.list(owner)).find(r=>r.plan.id===planId);if(saved){await session.open(saved.plan,saved);map=catalog.find(m=>m.id===saved.plan.mapId);floor=saved.plan.steps[0].items[0]?.floor||'ground';mode='tactics';}}if(shareId){shared=await cloud.shared(shareId);if(!alive)return;map=catalog.find(m=>m.id===shared.plan.mapId);floor=shared.plan.steps[0].items[0]?.floor||'ground';mode='tactics';}render();let acknowledged=false;try{acknowledged=localStorage.getItem(BETA_ACK)==='1';}catch{}if(!acknowledged)betaInfo();}catch(error){if(alive)root.innerHTML=`<div class="maps-app maps-empty"><h2>${shareId?'공유 전술을 열 수 없습니다.':'맵을 불러오지 못했습니다.'}</h2><p>${e(error.message)}</p>${button('reload','다시 시도')}<a class="btn" href="#v=maps">맵으로 돌아가기</a></div>`;}finally{clearTimeout(timer);}}
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',searchChange);window.addEventListener(ACCOUNT_CHANGED,accountChange);window.addEventListener('storage',accountChange);window.addEventListener('focus',accountChange);window.addEventListener('beforeunload',beforeUnload);document.addEventListener('visibilitychange',visibility);init();
 return ()=>{alive=false;stop();fetchController.abort();input?.destroy();if(session)session.destroy().finally(()=>storage.close());else storage.close();cloud.destroy();closeDialog();root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('input',searchChange);window.removeEventListener(ACCOUNT_CHANGED,accountChange);window.removeEventListener('storage',accountChange);window.removeEventListener('focus',accountChange);window.removeEventListener('beforeunload',beforeUnload);document.removeEventListener('visibilitychange',visibility);};
}
